<?php
declare(strict_types=1);
use Vendi\Database\Connection;use Vendi\Http\ApiGuard;use Vendi\Purchases\PurchaseOrderService;
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();header('Content-Type: application/json; charset=utf-8');
try{$u=ApiGuard::session();$db=Connection::make(['host'=>getenv('DB_HOST')?:'127.0.0.1','port'=>(int)(getenv('DB_PORT')?:3306),'database'=>getenv('DB_DATABASE')?:'vendi','username'=>getenv('DB_USERNAME')?:'root','password'=>getenv('DB_PASSWORD')?:'']);if($_SERVER['REQUEST_METHOD']==='GET')ApiGuard::permission($db,$u,'purchases.manage');else{ApiGuard::csrf();ApiGuard::permission($db,$u,'purchases.create');}$svc=new PurchaseOrderService($db);if($_SERVER['REQUEST_METHOD']==='GET'){$id=(int)($_GET['id']??0);echo json_encode(['ok'=>true,'order'=>$svc->detail((int)$u['business_id'],$id)],JSON_UNESCAPED_UNICODE);exit;}$d=json_decode(file_get_contents('php://input'),true,512,JSON_THROW_ON_ERROR);$id=$svc->create((int)$u['business_id'],(int)$u['default_branch_id'],(int)$d['supplier_id'],(int)$u['id'],$d['items']??[],$d['notes']??null);echo json_encode(['ok'=>true,'id'=>$id]);}catch(Throwable $e){http_response_code(422);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}